1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
22	    @Mapping(target = "initials", expression = "java(initials(owner))")
23	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
24	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
25	    @Mapping(target = "locality", expression = "java(locality(owner))")
26	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
27	    OwnerDto toOwnerDto(Owner owner);
28	
29	    /**
30	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when an email address
31	     * is present (non-null and non-blank), otherwise {@code 'PHONE'}.
32	     */
33	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
34	        if (owner == null) {
35	            return null;
36	        }
37	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
38	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
39	    }
40	
41	    /**
42	     * Fixed city-to-region table used to derive an owner's locality.
43	     */
44	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
45	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
46	
47	    /**
48	     * Derives the owner's locality from its city using the fixed city-to-region table
49	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). Returns the canonical region string,
50	     * or {@code 'UNKNOWN'} when the city is not in the table.
51	     */
52	    default String locality(Owner owner) {
53	        if (owner == null) {
54	            return null;
55	        }
56	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
57	    }
58	
59	    /**
60	     * Returns the owner's numeric membership level, assigned on creation. The level starts at
61	     * {@code 1}, gains {@code 1} when an email is present, gains {@code 1} when the owner has no
62	     * namesakes (namesakeCount is 0), and is capped at {@code 3} (level 4 is reserved for tenure).
63	     */
64	    default Integer membershipLevel(Owner owner) {
65	        if (owner == null) {
66	            return null;
67	        }
68	        int level = 1;
69	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
70	        if (hasEmail) {
71	            level++;
72	        }
73	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
74	        if (noNamesakes) {
75	            level++;
76	        }
77	        return Math.min(level, 3);
78	    }
79	
80	    /**
81	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the
82	     * last two digits of the registrationDate year, e.g. {@code 'SMI-0007-M26'}. Returns
83	     * {@code null} when the owner has no customer code or registration date.
84	     */
85	    default String membershipNumber(Owner owner) {
86	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
87	            return null;
88	        }
89	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
90	    }
91	
92	    /**
93	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
94	     */
95	    default String displayName(Owner owner) {
96	        if (owner == null) {
97	            return null;
98	        }
99	        return owner.getLastName() + ", " + owner.getFirstName();
100	    }
101	
102	    /**
103	     * Returns the owner's initials as the upper-cased first letters of firstName and
104	     * lastName, dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
105	     */
106	    default String initials(Owner owner) {
107	        if (owner == null) {
108	            return null;
109	        }
110	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
111	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
112	    }
113	
114	    Owner toOwner(OwnerDto ownerDto);
115	
116	    @Mapping(target = "id", ignore = true)
117	    @Mapping(target = "pets", ignore = true)
118	    Owner toOwner(OwnerFieldsDto ownerDto);
119	
120	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
121	
122	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
123	
124	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
125	        OwnerPageDto ownerPageDto = new OwnerPageDto();
126	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
127	        ownerPageDto.setPage(ownerPage.getNumber());
128	        ownerPageDto.setSize(ownerPage.getSize());
129	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
130	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
131	        return ownerPageDto;
132	    }
133	}
