17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
32	import org.springframework.security.access.AccessDeniedException;
33	import org.springframework.validation.BindingResult;
34	import org.springframework.validation.FieldError;
35	import org.springframework.web.bind.MethodArgumentNotValidException;
36	import org.springframework.web.bind.annotation.ControllerAdvice;
37	import org.springframework.web.bind.annotation.ExceptionHandler;
38	import org.springframework.web.bind.annotation.ResponseBody;
39	
40	/**
41	 * Global Exception handler for REST controllers.
42	 * <p>
43	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
44	 *
45	 * @author Vitaliy Fedoriv
46	 * @author Alexander Dudkin
47	 */
48	@ControllerAdvice
49	public class ExceptionControllerAdvice {
50	
51	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
52	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
53	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
54	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
55	    private static final String ERROR_DUPLICATE_TELEPHONE = "An owner with the given telephone already exists";
56	    private static final String ERROR_DUPLICATE_EMAIL = "An owner with the given email already exists";
57	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner with the given lastName and address already exists";
58	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
59	    private static final String ERROR_DAILY_LIMIT_EXCEEDED = "The maximum number of owners has already been created today";
60	
61	    /**
62	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
63	     * class.
64	     *
65	     * @param e     Object referring to the thrown exception.
66	     * @param status HTTP response status.
67	     * @param url URL request.
68	     */
69	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
70	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
71	        problemDetail.setType(URI.create(url.toString()));
72	        problemDetail.setTitle(e.getClass().getSimpleName());
73	        problemDetail.setDetail(detail);
74	        problemDetail.setProperty("timestamp", Instant.now());
75	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
76	        return problemDetail;
77	    }
78	
79	    /**
80	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
81	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
82	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
83	     * would catch it and report an authorization failure as a 500.
84	     *
85	     * @param e The {@link AccessDeniedException} to propagate
86	     * @throws AccessDeniedException always
87	     */
88	    @ExceptionHandler(AccessDeniedException.class)
89	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
90	        throw e;
91	    }
92	
93	    /**
94	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
95	     *
96	     * @param e The {@link Exception} to be handled
97	     * @param request {@link HttpServletRequest} object referring to the current request.
98	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
99	     */
100	    @ExceptionHandler(Exception.class)
101	    @ResponseBody
102	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
103	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
104	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
105	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
106	        return ResponseEntity.status(status).body(detail);
107	    }
108	
109	    /**
110	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
111	     * method returns a 404 Not Found status if an entity does not exist.
112	     *
113	     * @param e The {@link DataIntegrityViolationException} to be handled
114	     * @param request {@link HttpServletRequest} object referring to the current request.
115	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
116	     */
117	    @ExceptionHandler(DataIntegrityViolationException.class)
118	    @ResponseBody
119	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
120	        logger.warn("Data integrity violation at {} {}: {}",
121	            request.getMethod(),
122	            request.getRequestURI(),
123	            e.getMessage());
124	        logger.debug("Data integrity violation stacktrace", e);
125	        HttpStatus status = HttpStatus.NOT_FOUND;
126	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
127	        return ResponseEntity.status(status).body(detail);
128	    }
129	
130	    /**
131	     * Handles exception thrown by Bean Validation on controller methods parameters
132	     *
133	     * @param e The {@link MethodArgumentNotValidException} to be handled
134	     * @param request {@link HttpServletRequest} object referring to the current request.
135	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
136	     */
137	    @ExceptionHandler(MethodArgumentNotValidException.class)
138	    @ResponseBody
139	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
140	        HttpStatus status = HttpStatus.BAD_REQUEST;
141	        BindingResult bindingResult = e.getBindingResult();
142	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
143	        if (bindingResult.hasErrors()) {
144	            logger.debug("Validation error at {} {}: {}",
145	                request.getMethod(),
146	                request.getRequestURI(),
147	                bindingResult.getFieldErrors());
148	            detail.setProperty("schemaValidationErrors", schemaValidationErrors(bindingResult));
149	            detail.setProperty("errors", bindingResult.getFieldErrors().stream()
150	                .map(FieldError::getField)
151	                .distinct()
152	                .toList());
153	        }
154	        return ResponseEntity.status(status).body(detail);
155	    }
156	
157	    /**
158	     * Handles {@link RequiredFieldsMissingException} thrown when a request omits or leaves
159	     * blank one or more required fields. Returns a 400 Bad Request whose {@code errors}
160	     * property lists the name of each offending field.
161	     *
162	     * @param e The {@link RequiredFieldsMissingException} to be handled
163	     * @param request {@link HttpServletRequest} object referring to the current request.
164	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
165	     */
166	    @ExceptionHandler(RequiredFieldsMissingException.class)
167	    @ResponseBody
168	    public ResponseEntity<ProblemDetail> handleRequiredFieldsMissingException(RequiredFieldsMissingException e, HttpServletRequest request) {
169	        HttpStatus status = HttpStatus.BAD_REQUEST;
170	        logger.debug("Missing or blank required fields at {} {}: {}",
171	            request.getMethod(),
172	            request.getRequestURI(),
173	            e.getFields());
174	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
175	        detail.setProperty("errors", e.getFields());
176	        return ResponseEntity.status(status).body(detail);
177	    }
178	
179	    /**
180	     * Handles {@link InvalidFieldsException} thrown when a request supplies one or more
181	     * fields whose value is present but fails a business rule (for example a telephone
182	     * that does not normalize to exactly ten digits). Returns a 400 Bad Request whose
183	     * {@code errors} property lists the name of each offending field.
184	     *
185	     * @param e The {@link InvalidFieldsException} to be handled
186	     * @param request {@link HttpServletRequest} object referring to the current request.
187	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
188	     */
189	    @ExceptionHandler(InvalidFieldsException.class)
190	    @ResponseBody
191	    public ResponseEntity<ProblemDetail> handleInvalidFieldsException(InvalidFieldsException e, HttpServletRequest request) {
192	        HttpStatus status = HttpStatus.BAD_REQUEST;
193	        logger.debug("Invalid field values at {} {}: {}",
194	            request.getMethod(),
195	            request.getRequestURI(),
196	            e.getFields());
197	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
198	        detail.setProperty("errors", e.getFields());
199	        return ResponseEntity.status(status).body(detail);
200	    }
201	
202	    /**
203	     * Handles {@link DuplicateTelephoneException} thrown when a request tries to create an owner
204	     * whose normalized telephone is already used by another owner. Returns a 409 Conflict.
205	     *
206	     * @param e The {@link DuplicateTelephoneException} to be handled
207	     * @param request {@link HttpServletRequest} object referring to the current request.
208	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
209	     */
210	    @ExceptionHandler(DuplicateTelephoneException.class)
211	    @ResponseBody
212	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
213	        HttpStatus status = HttpStatus.CONFLICT;
214	        logger.debug("Duplicate telephone at {} {}: {}",
215	            request.getMethod(),
216	            request.getRequestURI(),
217	            e.getMessage());
218	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
219	        return ResponseEntity.status(status).body(detail);
220	    }
221	
222	    /**
223	     * Handles {@link DuplicateEmailException} thrown when a request tries to create an owner
224	     * whose lower-cased email is already used by another owner. Returns a 409 Conflict.
225	     *
226	     * @param e The {@link DuplicateEmailException} to be handled
227	     * @param request {@link HttpServletRequest} object referring to the current request.
228	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
229	     */
230	    @ExceptionHandler(DuplicateEmailException.class)
231	    @ResponseBody
232	    public ResponseEntity<ProblemDetail> handleDuplicateEmailException(DuplicateEmailException e, HttpServletRequest request) {
233	        HttpStatus status = HttpStatus.CONFLICT;
234	        logger.debug("Duplicate email at {} {}: {}",
235	            request.getMethod(),
236	            request.getRequestURI(),
237	            e.getMessage());
238	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_EMAIL);
239	        return ResponseEntity.status(status).body(detail);
240	    }
241	
242	    /**
243	     * Handles {@link DuplicateHouseholdException} thrown when a request tries to create an owner
244	     * whose lastName and address already belong to another owner and the request has not opted in
245	     * via {@code sharesHousehold}. Returns a 409 Conflict.
246	     *
247	     * @param e The {@link DuplicateHouseholdException} to be handled
248	     * @param request {@link HttpServletRequest} object referring to the current request.
249	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
250	     */
251	    @ExceptionHandler(DuplicateHouseholdException.class)
252	    @ResponseBody
253	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
254	        HttpStatus status = HttpStatus.CONFLICT;
255	        logger.debug("Duplicate household at {} {}: {}",
256	            request.getMethod(),
257	            request.getRequestURI(),
258	            e.getMessage());
259	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_HOUSEHOLD);
260	        return ResponseEntity.status(status).body(detail);
261	    }
262	
263	    /**
264	     * Handles {@link CityCapacityExceededException} thrown when a request tries to create an owner
265	     * whose city already contains the maximum number of owners. Returns a 409 Conflict.
266	     *
267	     * @param e The {@link CityCapacityExceededException} to be handled
268	     * @param request {@link HttpServletRequest} object referring to the current request.
269	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
270	     */
271	    @ExceptionHandler(CityCapacityExceededException.class)
272	    @ResponseBody
273	    public ResponseEntity<ProblemDetail> handleCityCapacityExceededException(CityCapacityExceededException e, HttpServletRequest request) {
274	        HttpStatus status = HttpStatus.CONFLICT;
275	        logger.debug("City at capacity at {} {}: {}",
276	            request.getMethod(),
277	            request.getRequestURI(),
278	            e.getMessage());
279	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
280	        return ResponseEntity.status(status).body(detail);
281	    }
282	
283	    /**
284	     * Handles {@link DailyOwnerLimitExceededException} thrown when a request tries to create an owner
285	     * once the maximum number of owners for the current day has already been created. Returns a
286	     * 429 Too Many Requests.
287	     *
288	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
289	     * @param request {@link HttpServletRequest} object referring to the current request.
290	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
291	     */
292	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
293	    @ResponseBody
294	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
295	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
296	        logger.debug("Daily owner limit exceeded at {} {}: {}",
297	            request.getMethod(),
298	            request.getRequestURI(),
299	            e.getMessage());
300	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT_EXCEEDED);
301	        return ResponseEntity.status(status).body(detail);
302	    }
303	
304	    /**
305	     * Renders the field-level errors of a {@link BindingResult} as the {@link ValidationMessageDto} list
306	     * exposed under the {@code schemaValidationErrors} property of the response.
307	     *
308	     * @param bindingResult The {@link BindingResult} carrying the rejected fields.
309	     * @return One {@link ValidationMessageDto} per field error.
310	     */
311	    private List<ValidationMessageDto> schemaValidationErrors(BindingResult bindingResult) {
312	        return bindingResult.getFieldErrors().stream()
313	            .map(fieldError -> {
314	                String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
315	                String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
316	                String message = "Field '%s' %s (rejected value: %s)".formatted(
317	                    fieldError.getField(),
318	                    defaultMessage,
319	                    rejectedValue);
320	                return new ValidationMessageDto(message)
321	                    .putAdditionalProperty("field", fieldError.getField())
322	                    .putAdditionalProperty("rejectedValue", rejectedValue)
323	                    .putAdditionalProperty("defaultMessage", defaultMessage);
324	            })
325	            .toList();
326	    }
327	
328	}
